-- Sample database: Music Store
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE artists (
  id       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name     varchar(120) NOT NULL,
  country  varchar(60)
);
CREATE TABLE albums (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title         varchar(160) NOT NULL,
  artist_id     integer NOT NULL REFERENCES artists(id),
  release_year  integer
);
CREATE TABLE tracks (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          varchar(200) NOT NULL,
  album_id      integer REFERENCES albums(id),
  genre         varchar(40) NOT NULL,
  composer      varchar(200),
  milliseconds  integer NOT NULL,
  unit_price    numeric(6,2) NOT NULL
);
CREATE TABLE playlists (
  id    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name  varchar(120) NOT NULL
);
CREATE TABLE playlist_tracks (
  playlist_id integer NOT NULL REFERENCES playlists(id),
  track_id    integer NOT NULL REFERENCES tracks(id),
  PRIMARY KEY (playlist_id, track_id)
);
CREATE TABLE invoices (
  id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_name     varchar(100) NOT NULL,
  customer_email    varchar(120) NOT NULL,
  billing_country   varchar(60) NOT NULL,
  invoice_date      timestamp NOT NULL,
  total             numeric(10,2) NOT NULL
);
CREATE TABLE invoice_items (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_id  integer NOT NULL REFERENCES invoices(id),
  track_id    integer NOT NULL REFERENCES tracks(id),
  unit_price  numeric(6,2) NOT NULL,
  quantity    integer NOT NULL DEFAULT 1
);
CREATE INDEX idx_albums_artist ON albums(artist_id);
CREATE INDEX idx_tracks_album ON tracks(album_id);
CREATE INDEX idx_inv_items_invoice ON invoice_items(invoice_id);
CREATE INDEX idx_inv_items_track ON invoice_items(track_id);

COMMENT ON TABLE artists IS 'ศิลปิน — บางรายยังไม่มีอัลบั้ม';
COMMENT ON TABLE albums IS 'อัลบั้ม';
COMMENT ON TABLE tracks IS 'เพลง — composer อาจเป็น NULL, single บางเพลงไม่มี album (album_id NULL)';
COMMENT ON COLUMN tracks.milliseconds IS 'ความยาวเพลง (มิลลิวินาที)';
COMMENT ON TABLE playlists IS 'เพลย์ลิสต์ — บางรายการยังว่าง';
COMMENT ON TABLE playlist_tracks IS 'ตารางเชื่อม many-to-many ระหว่าง playlists และ tracks';
COMMENT ON TABLE invoices IS 'ใบแจ้งหนี้ — total = SUM(unit_price * quantity) ของ invoice_items';
COMMENT ON TABLE invoice_items IS 'รายการเพลงในใบแจ้งหนี้';

















